import React from 'react';
import CloseIcon from '@mui/icons-material/Close';
import { Box, Stack, Typography } from '@mui/material';
import {
  Badge,
  Button,
  Dialog,
  IconButton,
  SearchableSelect,
} from '../../../../components/ui';
import { RECORD_COPY } from '../constants/recordCopy';
import useLeadAssignment from '../hooks/useLeadAssignment';
import {
  formatAssignableUserLabel,
  getLeadIdsFromRow,
  getUserId,
  getUserLabel,
  getUserProfileName,
  isUserAssigned,
} from '../utils/leadAssignmentUtils';

export default function LeadAssignModal({
  open,
  onClose,
  campaignId,
  leadIds,
  selectedRow = null,
  onSuccess,
}) {
  const resolvedLeadIds = leadIds?.length ? leadIds : getLeadIdsFromRow(selectedRow);
  const showCurrentAssignees = resolvedLeadIds.length === 1;
  const copy = RECORD_COPY.assign;

  const {
    users,
    loadingUsers,
    assignedUsers,
    selectedUsers,
    setSelectedUsers,
    queueUnassign,
    hasChanges,
    isSaving,
    submit,
  } = useLeadAssignment({
    open,
    campaignId,
    leadIds: resolvedLeadIds,
    selectedRow,
    showCurrentAssignees,
    onSuccess: () => {
      onSuccess?.();
      onClose?.();
    },
  });

  const handleSave = async () => {
    await submit();
  };

  return (
    <Dialog
      open={open}
      onClose={() => {
        if (!isSaving) onClose?.();
      }}
      title={copy.title}
      subtitle={copy.subtitle(resolvedLeadIds.length)}
      maxWidth="sm"
      actions={
        <>
          <Button variant="ghost" onClick={onClose} disabled={isSaving}>
            {copy.cancel}
          </Button>
          <Button
            variant="primary"
            loading={isSaving}
            disabled={isSaving || !hasChanges}
            onClick={handleSave}
          >
            {copy.save}
          </Button>
        </>
      }
    >
      <Stack spacing={2}>
        {showCurrentAssignees && assignedUsers.length > 0 ? (
          <Box>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
              {copy.currentlyAssigned}
            </Typography>
            <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap">
              {assignedUsers.map((user) => (
                <Badge key={getUserId(user)} variant="success" size="md">
                  {formatAssignableUserLabel(user)}
                  <IconButton
                    size="sm"
                    variant="ghost"
                    aria-label={copy.removeAssignee}
                    onClick={() => queueUnassign(user)}
                    disabled={isSaving}
                    sx={{ width: 20, height: 20, minWidth: 20, p: 0 }}
                  >
                    <CloseIcon sx={{ fontSize: 14 }} />
                  </IconButton>
                </Badge>
              ))}
            </Stack>
          </Box>
        ) : null}

        <SearchableSelect
          multiple
          options={users}
          value={selectedUsers}
          onChange={(value) => setSelectedUsers(Array.isArray(value) ? value : [])}
          label={copy.selectUsers}
          labelKey="username"
          valueKey="id"
          getOptionLabel={formatAssignableUserLabel}
          loading={loadingUsers}
          disabled={isSaving}
          getOptionDisabled={(option) => isUserAssigned(assignedUsers, option)}
          noOptionsText={copy.noUsers}
          renderOption={(props, option) => {
            const { key, ...optionProps } = props;
            const profileName = getUserProfileName(option);
            return (
              <Box component="li" key={key} {...optionProps}>
                <Box sx={{ display: 'flex', flexDirection: 'column', minWidth: 0, py: 0.25 }}>
                  <Typography variant="body2" noWrap>
                    {getUserLabel(option) || option.username}
                  </Typography>
                  {profileName ? (
                    <Typography variant="caption" color="text.secondary" noWrap>
                      {profileName}
                    </Typography>
                  ) : null}
                </Box>
              </Box>
            );
          }}
        />
      </Stack>
    </Dialog>
  );
}
