export const DOWNLOAD_EXCLUDED_COLUMN_KEYS = new Set(['audio_summary', 'aichat']);

export function getDownloadableColumns(columns = []) {
  return columns.filter((column) => column?.key && !DOWNLOAD_EXCLUDED_COLUMN_KEYS.has(column.key));
}

export function buildDownloadColumnSelection(columns = [], columnVisibility = {}) {
  return getDownloadableColumns(columns).reduce((selection, column) => {
    selection[column.key] = columnVisibility[column.key] !== false;
    return selection;
  }, {});
}

export function buildDownloadFilterPayload({
  workspaceId,
  tableId,
  filters = {},
}) {
  return {
    campaign_id: String(workspaceId ?? ''),
    leads_form_id: String(tableId ?? ''),
    start_date: filters.start_date || '',
    end_date: filters.end_date || '',
    dynamicFilters: Array.isArray(filters.dynamicFilters) ? filters.dynamicFilters : [],
  };
}

export function hasSelectedDownloadColumns(selectedColumns = {}) {
  return Object.values(selectedColumns).some(Boolean);
}

export function summarizeAppliedDownloadFilters({ filters = {}, search = '', activeFilterCount = 0 }) {
  const hasDateRange = Boolean(filters.start_date && filters.end_date);
  const hasSearch = Boolean(search);
  const hasDynamicFilters = activeFilterCount > 0;

  return {
    hasDateRange,
    hasSearch,
    hasDynamicFilters,
    hasAny: hasDateRange || hasSearch || hasDynamicFilters,
    dateRangeLabel: hasDateRange
      ? `${filters.start_date} to ${filters.end_date}`
      : 'No date range selected',
    searchLabel: hasSearch ? `"${search}"` : '',
    dynamicFilterCount: activeFilterCount,
  };
}

export function setAllDownloadColumns(selectedColumns = {}, visible = true) {
  return Object.keys(selectedColumns).reduce((next, key) => {
    next[key] = visible;
    return next;
  }, {});
}

export function toggleDownloadColumn(selectedColumns = {}, key, visible) {
  return {
    ...selectedColumns,
    [key]: visible,
  };
}
