import { getTemplateSheetParamColumns } from '../../../whatsapp-templates/utils/templateSendUtils';
import {
  divideKeyType,
  getTemplateParamNames,
  resolveParamValue,
} from './leadTemplateParamMapper';
import { resolveRowColumnValue } from './leadTemplateColumnOptions';

export function inferColumnKeyForParam(paramName, columnsMeta = []) {
  const { role, key } = divideKeyType(paramName);
  if (role === 'agent') return '';

  const normalizedKey = key || String(paramName ?? '');
  const match = (columnsMeta ?? []).find(
    (column) =>
      column?.key === normalizedKey
      || column?.fieldMeta?.key_name === normalizedKey
      || column?.fieldMeta?.key_name === paramName
      || column?.header === normalizedKey
  );

  return match?.key ?? '';
}

export function buildInitialBulkColumnMap(template, columnsMeta = []) {
  const map = {};
  getTemplateParamNames(template).forEach(({ name }) => {
    const columnKey = inferColumnKeyForParam(name, columnsMeta);
    if (columnKey) {
      map[name] = columnKey;
    }
  });
  return map;
}

export function resolveParamValueWithColumnMap(
  paramName,
  row,
  loggedInUser,
  columnsMeta = [],
  paramColumnMap = {}
) {
  const columnKey = paramColumnMap?.[paramName];
  if (columnKey) {
    return resolveRowColumnValue(row, columnKey, columnsMeta);
  }
  return resolveParamValue(paramName, row, loggedInUser, columnsMeta);
}

export function mapRowToBodyParamsWithColumnMap(
  template,
  row,
  loggedInUser,
  columnsMeta = [],
  paramColumnMap = {}
) {
  return getTemplateParamNames(template).map(({ name, label }) => ({
    type: 'text',
    text: resolveParamValueWithColumnMap(
      name,
      row,
      loggedInUser,
      columnsMeta,
      paramColumnMap
    ),
    label,
    paramName: name,
  }));
}

export function mapRowToSheetRowWithColumnMap(
  template,
  row,
  loggedInUser,
  columnsMeta = [],
  paramColumnMap = {}
) {
  const sheetRow = {};
  const sheetColumns = getTemplateSheetParamColumns(template);
  getTemplateParamNames(template).forEach(({ name, label }, index) => {
    const sheetKey = sheetColumns[index] ?? label ?? name;
    sheetRow[sheetKey] = resolveParamValueWithColumnMap(
      name,
      row,
      loggedInUser,
      columnsMeta,
      paramColumnMap
    );
  });
  return sheetRow;
}

export function buildBulkMappingFields(template, paramColumnMap = {}, columnsMeta = []) {
  return getTemplateParamNames(template).map(({ name, label }, index) => {
    const { role } = divideKeyType(name);
    const isAgentParam = role === 'agent';
    return {
      paramName: name,
      label,
      variableIndex: index + 1,
      columnKey: paramColumnMap[name] ?? '',
      isAgentParam,
      requiresColumn: !isAgentParam && columnsMeta.length > 0,
    };
  });
}

export function areBulkColumnMappingsComplete(fields = []) {
  return fields.every((field) => {
    if (!field.requiresColumn) return true;
    return Boolean(String(field.columnKey ?? '').trim());
  });
}
