import { convertToReadableFormat } from '../../../../utils/helper.jsx';

export function toFilterOptions(arr = []) {
  return arr.map((value) => {
    const str = String(value);
    return { label: convertToReadableFormat(str), value: str };
  });
}

export function normalizeFormItems(formItems) {
  if (!formItems) return [];
  if (Array.isArray(formItems)) return formItems.filter(Boolean);
  if (typeof formItems === 'object') return Object.values(formItems).filter(Boolean);
  return [];
}

export function getStatusNamesByType(list = [], typeKey) {
  if (!typeKey) return [];
  try {
    return list
      .filter((item) => (item?.type_of_status ?? item?.type) === typeKey)
      .map((item) => item.status_name)
      .filter(Boolean);
  } catch {
    return [];
  }
}

export function getScopedSubStatusFilterOptions(typeOfStatusList = {}, filter = {}, filters = []) {
  const allOptions = typeOfStatusList[filter?.key_name] || [];
  const parentKey = filter?.status_parent_key;
  if (!parentKey) {
    return allOptions;
  }

  const parentFilter = (filters || []).find(
    (item) => item?.key_name === parentKey && item?.statusOption === 'is_status'
  );
  if (!parentFilter?.status_id) {
    return allOptions;
  }

  return allOptions.filter((entry) => entry?.status_id === parentFilter.status_id);
}

export function getSubStatusNamesByParent(list = [], parentKey) {
  if (!parentKey) return [];
  try {
    const pickSubs = (item) =>
      item?.substatuses ?? item?.sub_status ?? item?.subStatus ?? item?.children ?? item?.options ?? [];

    return list
      .filter((item) => (item?.type_of_status ?? item?.type) === parentKey)
      .flatMap((item) => pickSubs(item))
      .map((entry) => entry?.name ?? entry?.label ?? entry)
      .filter(Boolean);
  } catch {
    return [];
  }
}

export function buildTypeOfStatusList(statusList = []) {
  const statusData = {};

  statusList.forEach((item) => {
    if (item?.type_of_status) {
      if (!statusData[item.type_of_status]) {
        statusData[item.type_of_status] = [];
      }
      const { substatuses, ...rest } = item;
      statusData[item.type_of_status].push(rest);
    }

    item?.substatuses?.forEach((sub) => {
      const key = sub?.type_of_status || 'unknown';
      if (!statusData[key]) {
        statusData[key] = [];
      }
      statusData[key].push({
        ...sub,
        status_id: item?.status_id,
        status_name: item?.status_name,
      });
    });
  });

  return statusData;
}

export function getOperatorsForFieldType(fieldType = '') {
  const base = [
    { value: 'equals', label: 'Equals' },
    { value: 'not_equals', label: 'Not Equals' },
    { value: 'is_empty', label: 'Is Empty' },
    { value: 'is_not_empty', label: 'Is Not Empty' },
  ];
  const textOps = [
    { value: 'contains', label: 'Contains' },
    { value: 'starts_with', label: 'Starts With' },
    { value: 'ends_with', label: 'Ends With' },
  ];
  const rangeOps = [
    { value: 'gt', label: 'Greater Than' },
    { value: 'gte', label: 'Greater or Equal' },
    { value: 'lt', label: 'Less Than' },
    { value: 'lte', label: 'Less or Equal' },
    { value: 'range', label: 'Between' },
  ];
  const timeRange = [
    { value: 'gt', label: 'Greater Than' },
    { value: 'gte', label: 'Greater or Equal' },
    { value: 'lt', label: 'Less Than' },
    { value: 'lte', label: 'Less or Equal' },
  ];

  switch (fieldType) {
    case 'STRING':
    case 'EMAIL':
    case 'TEXT':
    case 'TEXTAREA':
      return [...base, ...textOps];
    case 'INT':
    case 'FLOAT':
      return [...base, ...rangeOps];
    case 'DATE':
    case 'TIME':
      return [...base, ...timeRange];
    case 'BOOLEAN':
      return [
        { value: 'equals', label: 'Equals' },
        { value: 'not_equals', label: 'Not Equals' },
      ];
    case 'CHECKBOX':
    case 'RADIO':
    case 'DROPDOWN':
      return base;
    default:
      return [...base, ...textOps];
  }
}

export function buildInitialFiltersArray(formItems = []) {
  return normalizeFormItems(formItems)
    .filter((field) => field?.isFilter)
    .map((field) => {
      const defaultValue = field.key_type === 'BOOLEAN'
        ? null
        : field.key_type === 'CHECKBOX'
          ? []
          : '';

      return {
        key_name: field.key_name,
        value: defaultValue,
        operator: field.key_type === 'DATE' ? 'range' : 'equals',
        field_type: field.key_type,
        alias_name: field.alias_name,
        key_options: field.key_options || [],
        statusOption: field.statusOption || null,
        status_id: field.status_id || null,
        status_parent_key: field.status_parent_key || null,
      };
    });
}

export function hydrateFiltersWithStatusOptions(filtersArray = [], formItems = [], statusList = []) {
  const items = normalizeFormItems(formItems);

  return filtersArray.map((filter) => {
    const raw = items.find((item) => item?.key_name === filter.key_name);
    if (!raw) return filter;

    if (raw.statusOption === 'is_status') {
      return {
        ...filter,
        key_options: getStatusNamesByType(statusList, raw.key_name),
      };
    }

    if (raw.statusOption === 'is_sub_status') {
      return {
        ...filter,
        key_options: getSubStatusNamesByParent(statusList, raw.status_parent_key),
      };
    }

    return filter;
  });
}

export function normalizeSavedDynamicFilters(saved = []) {
  return saved.map((entry) => ({
    key_name: entry?.matched_with?.key_name,
    value: entry?.custom_value ?? '',
    operator: entry?.operator || 'equals',
    field_type: entry?.valueType || 'STRING',
    alias_name: entry?.matched_with?.key_name,
    statusOption: entry?.statusOption || null,
    status_id: entry?.param?.status_id || null,
    sub_status_id: entry?.param?.sub_status_id || null,
  }));
}

export function isActiveDynamicFilter(filter) {
  if (!filter) return false;
  if (['is_empty', 'is_not_empty'].includes(filter.operator)) return true;

  if (filter.field_type === 'BOOLEAN') {
    return filter.value === true || filter.value === false;
  }

  if (Array.isArray(filter.value)) {
    return filter.value.length > 0;
  }

  if (filter.value && typeof filter.value === 'object') {
    return Object.values(filter.value).some(
      (value) => value !== '' && value !== null && value !== undefined
    );
  }

  return filter.value !== '' && filter.value !== null && filter.value !== undefined;
}

function getValueTypeByFieldType(fieldType) {
  switch (fieldType) {
    case 'INT':
    case 'FLOAT':
    case 'PINCODE':
    case 'NUMBER':
      return 'number';
    case 'BOOLEAN':
      return 'boolean';
    case 'DATE':
      return 'date';
    case 'TIME':
      return 'time';
    default:
      return 'string';
  }
}

export function transformDynamicFilters(filters = []) {
  return filters.map((filter) => {
    const rule = {
      left: 'others',
      operator: filter.operator || 'equals',
      valueType: getValueTypeByFieldType(filter.field_type),
      caseInsensitive: true,
      trim: true,
      matched_with: {
        key_name: filter.key_name,
      },
      matched_field_type: 'dynamic',
    };

    const isStatus = filter.statusOption === 'is_status';
    const isSubStatus = filter.statusOption === 'is_sub_status';

    if (!isStatus && !isSubStatus) {
      rule.custom_value =
        filter.value === undefined || filter.value === null ? '' : filter.value;
    }

    if (isStatus) {
      rule.param = {
        status_id: filter.status_id || '',
      };
    }

    if (isSubStatus) {
      rule.param = {
        sub_status_id: filter.sub_status_id || '',
      };
    }

    return rule;
  });
}

export function mergeDynamicFilterRules(previous = [], current = []) {
  const map = new Map();

  previous.forEach((rule) => {
    const key = rule?.matched_with?.key_name;
    if (key) map.set(key, rule);
  });

  current.forEach((rule) => {
    const key = rule?.matched_with?.key_name;
    if (key) map.set(key, rule);
  });

  return Array.from(map.values());
}

export function applySavedFiltersToArray(filtersArray = [], appliedFilters = {}) {
  const savedDynamicFilters = Array.isArray(appliedFilters.dynamicFilters)
    ? normalizeSavedDynamicFilters(appliedFilters.dynamicFilters)
    : [];

  return filtersArray.map((filter) => {
    const saved = savedDynamicFilters.find((entry) => entry.key_name === filter.key_name);
    if (!saved) return filter;

    return {
      ...filter,
      value: saved.value,
      operator: saved.operator,
      statusOption: saved.statusOption || filter.statusOption,
      status_id: saved.status_id || filter.status_id,
      sub_status_id: saved.sub_status_id || filter.sub_status_id,
    };
  });
}

export function resetFiltersArray(filtersArray = []) {
  return filtersArray.map((filter) => ({
    ...filter,
    value: filter.field_type === 'BOOLEAN'
      ? null
      : filter.field_type === 'CHECKBOX'
        ? []
        : '',
    operator: filter.field_type === 'DATE' ? 'range' : 'equals',
    status_id: '',
    sub_status_id: '',
  }));
}
