import React, { useMemo } from 'react';
import { Typography } from '@mui/material';
import { DataTable, EmptyState, RowActionsMenu, TableSkeleton } from '../../../../../components/ui';
import { CAMPAIGN_COPY } from '../../../constants/campaignCopy';
import { buildRowActions } from '../../../records/components/RowActions';
import RecordTableCell from '../../../records/components/cells/RecordTableCell';
import { COMMENT_COLUMN_KEY } from '../../../records/utils/recordInteractiveColumnUtils';
import { getUnreadCountForRow } from '../../../records/chat/utils/leadChatUnreadUtils';
import LeadColumnHeader from './LeadColumnHeader';
import LeadPrimaryCell from './LeadPrimaryCell';

const INTERACTIVE_ROW_SELECTORS = [
  'button',
  'a',
  'input',
  '[role="combobox"]',
  '[role="option"]',
  '.MuiPopover-root',
  '.MuiMenu-root',
  '.MuiAutocomplete-root',
  '.record-cell-action',
].join(', ');

const PRIMARY_COLUMN_KEYS = new Set(['lead_id', 'phone_number', 'contact_name']);

function renderHeader(label) {
  return () => <LeadColumnHeader>{label}</LeadColumnHeader>;
}

function WorkspaceIndexCell({ page, pageSize, rowIndex }) {
  const serial = page * pageSize + rowIndex + 1;

  return (
    <Typography
      component="span"
      sx={{
        fontSize: '0.8125rem',
        fontWeight: 500,
        fontVariantNumeric: 'tabular-nums',
        color: 'text.secondary',
      }}
    >
      {serial}
    </Typography>
  );
}

function useWorkspaceTableColumns({
  columnsMeta = [],
  page,
  pageSize,
  rowPermissions = {},
  tableOverrides = {},
  onView,
  onEdit,
  onDelete,
  onOpenRowModal,
  onOpenLeadChat,
  typeOfStatusList,
  optionColorsByAlias,
  onRequestStatusUpdate,
  onEntityChange,
  columnActions = {},
  selectedCount = 0,
  rowSelection = {},
  unreadLeadIds = new Set(),
  unreadCountByLeadId = new Map(),
}) {
  return useMemo(() => {
    const indexColumn = {
      id: 'index',
      header: 'S.No.',
      Header: renderHeader('S.No.'),
      size: 52,
      enableSorting: false,
      muiTableBodyCellProps: {
        sx: {
          overflow: 'visible',
          textOverflow: 'unset',
          whiteSpace: 'nowrap',
        },
      },
      Cell: ({ row }) => (
        <WorkspaceIndexCell page={page} pageSize={pageSize} rowIndex={row.index} />
      ),
    };

    const dataColumns = columnsMeta.map((column) => {
      const headerLabel = column.header ?? column.key;
      const isPrimaryColumn = PRIMARY_COLUMN_KEYS.has(column.key)
        || column.fieldMeta?.key_name === 'lead_id';
      const isCommentColumn = column.key === COMMENT_COLUMN_KEY
        || column.fieldMeta?.key_name === COMMENT_COLUMN_KEY;

      return {
        accessorKey: column.key,
        header: headerLabel,
        Header: renderHeader(headerLabel),
        size: isPrimaryColumn ? 260 : isCommentColumn ? 240 : undefined,
        minSize: isCommentColumn ? 180 : undefined,
        enableSorting: column.fieldMeta?.key_type !== 'ENTITY',
        muiTableBodyCellProps: isPrimaryColumn || isCommentColumn
          ? {
              sx: {
                overflow: 'visible',
                position: isPrimaryColumn ? 'relative' : undefined,
              },
            }
          : undefined,
        Cell: ({ cell, row }) => {
          if (column.key === 'lead_id' || column.fieldMeta?.key_name === 'lead_id') {
            return (
              <LeadPrimaryCell
                row={row.original}
                onView={onView}
                isUnread={unreadLeadIds.has(String(row.original?.lead_id ?? row.original?.id ?? ''))}
              />
            );
          }

          return (
            <RecordTableCell
              row={row.original}
              value={cell.getValue()}
              column={column}
              typeOfStatusList={typeOfStatusList}
              optionColorsByAlias={optionColorsByAlias}
              canEdit={rowPermissions.canEdit}
              columnActions={columnActions}
              onRequestStatusUpdate={onRequestStatusUpdate}
              onEntityChange={onEntityChange}
            />
          );
        },
      };
    });

    const actionsColumn = {
      id: 'actions',
      header: 'Action',
      Header: renderHeader('Action'),
      size: 72,
      minSize: 72,
      maxSize: 72,
      enableSorting: false,
      enablePinning: true,
      muiTableHeadCellProps: {
        sx: tableOverrides.actionColumnHeadCell,
      },
      muiTableBodyCellProps: {
        sx: tableOverrides.actionColumnBodyCell,
      },
      Cell: ({ row }) => {
        const rowId = String(row.original?.id ?? '');
        const isRowSelected = Boolean(rowSelection[rowId]);
        const unreadCount = getUnreadCountForRow(row.original, unreadCountByLeadId);

        return (
          <RowActionsMenu
            actions={buildRowActions({
              row: row.original,
              permissions: rowPermissions,
              selectedCount,
              isRowSelected,
              onEdit,
              onDelete,
              onOpenRowModal,
              onOpenLeadChat,
              onOpenAudioSummary: columnActions.onOpenAudioSummary,
            })}
            unreadCount={unreadCount}
          />
        );
      },
    };

    return [indexColumn, ...dataColumns, actionsColumn];
  }, [
    columnActions,
    columnsMeta,
    onDelete,
    onEdit,
    onEntityChange,
    onOpenRowModal,
    onOpenLeadChat,
    onRequestStatusUpdate,
    optionColorsByAlias,
    page,
    pageSize,
    rowPermissions,
    rowSelection,
    selectedCount,
    tableOverrides.actionColumnBodyCell,
    tableOverrides.actionColumnHeadCell,
    typeOfStatusList,
    unreadLeadIds,
    unreadCountByLeadId,
  ]);
}

export default function TableRecordsList({
  rows = [],
  columnsMeta = [],
  loading,
  page,
  pageSize,
  tableOverrides,
  enableSorting = false,
  sorting = [],
  onSortingChange,
  enableRowSelection = false,
  rowSelection = {},
  onRowSelectionChange,
  onRowClick,
  canEdit = false,
  canDelete = false,
  rowPermissions = {},
  onEdit,
  onDelete,
  onOpenRowModal,
  onOpenLeadChat,
  typeOfStatusList = {},
  optionColorsByAlias = {},
  onRequestStatusUpdate,
  onEntityChange,
  columnActions = {},
  selectedCount = 0,
  unreadLeadIds = new Set(),
  unreadCountByLeadId = new Map(),
}) {
  const safeOverrides = tableOverrides ?? {};

  const columns = useWorkspaceTableColumns({
    columnsMeta,
    page,
    pageSize,
    rowPermissions,
    tableOverrides: safeOverrides,
    onView: onRowClick,
    onEdit,
    onDelete,
    onOpenRowModal,
    onOpenLeadChat,
    typeOfStatusList,
    optionColorsByAlias,
    onRequestStatusUpdate,
    onEntityChange,
    columnActions,
    selectedCount,
    rowSelection,
    unreadLeadIds,
    unreadCountByLeadId,
  });

  return (
    <DataTable
      columns={columns}
      data={rows}
      loading={loading}
      getRowId={(row) => String(row.id)}
      aria-label={CAMPAIGN_COPY.detail.tableRecordsAriaLabel}
      enableSorting={enableSorting}
      enableRowSelection={enableRowSelection}
      enableColumnPinning
      initialState={{
        density: 'compact',
        columnPinning: { right: ['actions'] },
      }}
      state={{
        sorting,
        rowSelection,
      }}
      onSortingChange={onSortingChange}
      onRowSelectionChange={onRowSelectionChange}
      muiTableHeadRowProps={safeOverrides.muiTableHeadRowProps}
      muiTableBodyRowProps={({ row }) => {
        const isUnread = unreadLeadIds.has(String(row.original?.lead_id ?? row.original?.id ?? ''));
        const baseSx = typeof safeOverrides.muiTableBodyRowProps?.sx === 'object'
          ? safeOverrides.muiTableBodyRowProps.sx
          : {};

        return {
          ...safeOverrides.muiTableBodyRowProps,
          onClick: (event) => {
            if (event.target.closest(INTERACTIVE_ROW_SELECTORS)) return;
            onRowClick?.(row.original);
          },
          'aria-label': isUnread ? 'New lead' : undefined,
          sx: {
            ...baseSx,
            cursor: onRowClick ? 'pointer' : 'default',
            ...(isUnread ? {
              boxShadow: 'inset 3px 0 0 #22C55E',
              '& td': {
                backgroundColor: '#ECFDF3 !important',
              },
              '&:hover td': {
                backgroundColor: '#D1FAE5 !important',
              },
            } : {}),
          },
        };
      }}
      emptyState={
        <EmptyState
          title="No records found"
          description="Try adjusting your search or add new records to this table."
        />
      }
      skeleton={
        <TableSkeleton
          rowCount={pageSize}
          columnCount={Math.max(columnsMeta.length + 2, 4)}
        />
      }
      muiTableHeadCellProps={safeOverrides.muiTableHeadCellProps}
      muiTableBodyCellProps={safeOverrides.muiTableBodyCellProps}
      muiTableContainerProps={safeOverrides.muiTableContainerProps}
    />
  );
}
