import { COVERAGE_STATUS } from './leadTemplateCoverage';

export function buildBulkGapLines(coverage) {
  if (!coverage?.items?.length) return [];

  return coverage.items
    .filter(
      (item) =>
        item.status === COVERAGE_STATUS.MISSING
        || item.status === COVERAGE_STATUS.PARTIAL
    )
    .map((item) => ({
      paramName: item.paramName,
      label: item.label || item.paramName,
      filledCount: item.filledCount,
      totalRows: item.totalRows,
      missingCount: Math.max(item.totalRows - item.filledCount, 0),
    }));
}

export function bulkNeedsSheetPath(coverage, selectedCount) {
  if (selectedCount <= 1 || !coverage) return false;
  return coverage.hasMissing || coverage.hasPartial;
}
