import { useCallback, useEffect, useMemo, useState } from 'react';
import { useRecoilValue } from 'recoil';
import { useSnackBar } from '../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { userInformationAtom } from '../../../../Services/_states/auth.js';
import { templateService } from '../../../whatsapp-templates/services/templateService';
import { getSampleSheetUrl } from '../../../whatsapp-templates/constants/templateApi';
import { parseBulkUploadError } from '../../../whatsapp-templates/utils/templateSendUtils';
import { analyzeParamCoverage } from '../utils/leadTemplateCoverage';
import { downloadLeadTemplateSampleSheet } from '../utils/buildLeadTemplateSampleSheet';
import { downloadLeadTemplateErrorSheet } from '../utils/buildLeadTemplateErrorSheet';
import { validateLeadTemplateSheetFile } from '../utils/validateLeadTemplateSheet';
import { sendTemplateToLeads } from '../utils/sendTemplateToLeads';
import {
  buildRecipientSubtitle,
  resolveDefaultBotNumber,
} from '../utils/leadTemplateSendUtils';
import { mapRowToBodyParams } from '../utils/leadTemplateParamMapper';
import {
  buildBulkMappingFields,
  buildInitialBulkColumnMap,
  mapRowToBodyParamsWithColumnMap,
} from '../utils/leadTemplateBulkColumnMap';
import {
  applyParamOverridesToBodyParams,
  areDirectSendOverridesValid,
  buildEditableParamFields,
  buildInitialParamOverrides,
} from '../utils/leadTemplateParamOverrides';
import {
  buildTemplateColumnOptions,
  resolveRowColumnValue,
} from '../utils/leadTemplateColumnOptions';
import { buildBulkGapLines } from '../utils/leadTemplateBulkSummary';
import { RECORD_COPY } from '../constants/recordCopy';

export default function useLeadTemplateSend({
  open,
  selectedRows = [],
  formPayload,
  columnsMeta = [],
  organisationId,
  onSuccess,
  onClose,
}) {
  const copy = RECORD_COPY.sendTemplate;
  const { showSnackBar } = useSnackBar();
  const loggedInUser = useRecoilValue(userInformationAtom);

  const [botNumber, setBotNumber] = useState('');
  const [selectedTemplateMeta, setSelectedTemplateMeta] = useState(null);
  const [resolvedTemplate, setResolvedTemplate] = useState(null);
  const [isLoadingTemplate, setIsLoadingTemplate] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [sendProgress, setSendProgress] = useState({ done: 0, total: 0 });
  const [sendSummary, setSendSummary] = useState(null);
  const [sheetFile, setSheetFile] = useState(null);
  const [sheetValidation, setSheetValidation] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [paramOverrides, setParamOverrides] = useState({});
  const [paramColumnMap, setParamColumnMap] = useState({});

  const isSingleRecipient = selectedRows.length === 1;

  const quickTemplates = useMemo(
    () => (Array.isArray(formPayload?.templates) ? formPayload.templates : []),
    [formPayload?.templates]
  );

  const organisation = useMemo(
    () =>
      organisationId
        ? {
            organisation_id: organisationId,
            name: loggedInUser?.profile?.organisation?.name ?? '',
          }
        : null,
    [loggedInUser?.profile?.organisation?.name, organisationId]
  );

  const subtitle = useMemo(
    () => buildRecipientSubtitle(selectedRows, copy),
    [copy, selectedRows]
  );

  const coverage = useMemo(() => {
    if (!resolvedTemplate) return null;
    return analyzeParamCoverage(
      resolvedTemplate,
      selectedRows,
      columnsMeta,
      loggedInUser
    );
  }, [columnsMeta, loggedInUser, resolvedTemplate, selectedRows]);

  const previewParams = useMemo(() => {
    if (!resolvedTemplate || !selectedRows.length) return [];
    const firstRow =
      selectedRows.find((row) => mapRowToBodyParams(resolvedTemplate, row, loggedInUser, columnsMeta).length) ??
      selectedRows[0];
    return mapRowToBodyParams(resolvedTemplate, firstRow, loggedInUser, columnsMeta);
  }, [columnsMeta, loggedInUser, resolvedTemplate, selectedRows]);

  const columnOptions = useMemo(
    () => buildTemplateColumnOptions(columnsMeta),
    [columnsMeta]
  );

  const editableFields = useMemo(() => {
    const fields = buildEditableParamFields(previewParams, paramOverrides);
    return fields.map((field) => ({
      ...field,
      columnKey: paramColumnMap[field.paramName] ?? '',
    }));
  }, [paramColumnMap, paramOverrides, previewParams]);

  const bulkMappingFields = useMemo(() => {
    if (!resolvedTemplate || isSingleRecipient) return [];
    return buildBulkMappingFields(resolvedTemplate, paramColumnMap, columnsMeta);
  }, [columnsMeta, isSingleRecipient, paramColumnMap, resolvedTemplate]);

  const gapLines = useMemo(
    () => buildBulkGapLines(coverage),
    [coverage]
  );

  const liveBodyParams = useMemo(() => {
    if (!resolvedTemplate || !selectedRows.length) return [];
    if (isSingleRecipient) {
      if (!previewParams.length) return [];
      return applyParamOverridesToBodyParams(previewParams, paramOverrides);
    }
    return mapRowToBodyParamsWithColumnMap(
      resolvedTemplate,
      selectedRows[0],
      loggedInUser,
      columnsMeta,
      paramColumnMap
    ).map((param) => ({
      type: param.type ?? 'text',
      text: param.text ?? '',
    }));
  }, [
    columnsMeta,
    isSingleRecipient,
    loggedInUser,
    paramColumnMap,
    paramOverrides,
    previewParams,
    resolvedTemplate,
    selectedRows,
  ]);

  const canSendDirect = useMemo(() => {
    if (!isSingleRecipient || !resolvedTemplate || !coverage?.phoneSummary?.withPhone) {
      return false;
    }
    return areDirectSendOverridesValid(previewParams, paramOverrides);
  }, [coverage, isSingleRecipient, paramOverrides, previewParams, resolvedTemplate]);

  const canUploadSend = useMemo(
    () =>
      Boolean(
        resolvedTemplate
        && !isSingleRecipient
        && sheetFile
        && sheetValidation?.valid
      ),
    [isSingleRecipient, resolvedTemplate, sheetFile, sheetValidation]
  );

  useEffect(() => {
    if (!open) {
      setParamOverrides({});
      setParamColumnMap({});
      setBotNumber('');
      setSelectedTemplateMeta(null);
      setResolvedTemplate(null);
      setIsSubmitting(false);
      setIsUploading(false);
      setSendProgress({ done: 0, total: 0 });
      setSendSummary(null);
      setSheetFile(null);
      setSheetValidation(null);
      setUploadProgress(0);
      return;
    }

    setBotNumber(resolveDefaultBotNumber(formPayload));
    setSendSummary(null);
    setSheetFile(null);
    setSheetValidation(null);
  }, [formPayload, open]);

  useEffect(() => {
    if (!open || !selectedTemplateMeta?.name || !botNumber) {
      setResolvedTemplate(null);
      return undefined;
    }

    let cancelled = false;
    setIsLoadingTemplate(true);

    templateService
      .getTemplate(selectedTemplateMeta.name, botNumber)
      .then((res) => {
        if (cancelled) return;
        const data = res?.data?.data ?? res?.data ?? null;
        setResolvedTemplate(data ? { ...data, bot_number: botNumber } : null);
      })
      .catch(() => {
        if (!cancelled) {
          setResolvedTemplate(null);
          showSnackBar(copy.templateLoadFailed, 'error');
        }
      })
      .finally(() => {
        if (!cancelled) setIsLoadingTemplate(false);
      });

    return () => {
      cancelled = true;
    };
  }, [botNumber, copy.templateLoadFailed, open, selectedTemplateMeta?.name, showSnackBar]);

  useEffect(() => {
    setParamOverrides({});
    setParamColumnMap({});
  }, [botNumber, selectedTemplateMeta?.name, selectedRows]);

  useEffect(() => {
    if (!open || !resolvedTemplate) return;
    if (isSingleRecipient) {
      const params = mapRowToBodyParams(
        resolvedTemplate,
        selectedRows[0],
        loggedInUser,
        columnsMeta
      );
      if (params.length) {
        setParamOverrides(buildInitialParamOverrides(params));
      }
      setParamColumnMap({});
      return;
    }
    setParamOverrides({});
    setParamColumnMap(buildInitialBulkColumnMap(resolvedTemplate, columnsMeta));
  }, [
    columnsMeta,
    isSingleRecipient,
    loggedInUser,
    open,
    resolvedTemplate,
    selectedRows,
  ]);

  const handleParamChange = useCallback((paramName, value) => {
    setParamOverrides((prev) => ({
      ...prev,
      [paramName]: value,
    }));
  }, []);

  const handleParamColumnSelect = useCallback(
    (paramName, columnKey) => {
      setParamColumnMap((prev) => ({
        ...prev,
        [paramName]: columnKey || '',
      }));

      if (isSingleRecipient && columnKey && selectedRows[0]) {
        const value = resolveRowColumnValue(selectedRows[0], columnKey, columnsMeta);
        setParamOverrides((prev) => ({
          ...prev,
          [paramName]: value,
        }));
      }
    },
    [columnsMeta, isSingleRecipient, selectedRows]
  );

  const selectQuickTemplate = useCallback((template) => {
    setSelectedTemplateMeta(template);
  }, []);

  const handleTemplateDropdownChange = useCallback((template) => {
    setSelectedTemplateMeta(template ?? null);
  }, []);

  const handleBotChange = useCallback((orgOrBot) => {
    const nextBot =
      orgOrBot?.wa_phone_number ??
      orgOrBot?.bot_number ??
      (typeof orgOrBot === 'string' ? orgOrBot : '');
    if (nextBot) {
      setBotNumber(String(nextBot));
      setSelectedTemplateMeta(null);
      setResolvedTemplate(null);
    }
  }, []);

  const downloadPrefilledSample = useCallback(() => {
    if (!resolvedTemplate) {
      showSnackBar(copy.selectTemplateFirst, 'warning');
      return;
    }
    downloadLeadTemplateSampleSheet(
      resolvedTemplate,
      selectedRows,
      loggedInUser,
      columnsMeta,
      isSingleRecipient ? null : paramColumnMap
    );
  }, [
    columnsMeta,
    copy.selectTemplateFirst,
    isSingleRecipient,
    loggedInUser,
    paramColumnMap,
    resolvedTemplate,
    selectedRows,
    showSnackBar,
  ]);

  const downloadBlankSample = useCallback(() => {
    if (!resolvedTemplate?.wa_Id) {
      showSnackBar(copy.selectTemplateFirst, 'warning');
      return;
    }
    window.location.href = getSampleSheetUrl(resolvedTemplate.wa_Id);
  }, [copy.selectTemplateFirst, resolvedTemplate?.wa_Id, showSnackBar]);

  const downloadErrorSheet = useCallback(() => {
    if (!resolvedTemplate || !sheetValidation?.rowResults?.length) {
      showSnackBar(copy.noErrorSheet, 'warning');
      return;
    }
    downloadLeadTemplateErrorSheet({
      template: resolvedTemplate,
      rowResults: sheetValidation.rowResults,
      guideLines: copy.errorSheetGuide,
    });
  }, [copy.errorSheetGuide, copy.noErrorSheet, resolvedTemplate, sheetValidation, showSnackBar]);

  const validateSheetFile = useCallback(
    async (file) => {
      if (!resolvedTemplate) {
        showSnackBar(copy.selectTemplateFirst, 'warning');
        return null;
      }
      const result = await validateLeadTemplateSheetFile(file, resolvedTemplate);
      setSheetValidation(result);
      return result;
    },
    [copy.selectTemplateFirst, resolvedTemplate, showSnackBar]
  );

  const handleSheetFileSelect = useCallback(
    async (file) => {
      setSheetFile(file ?? null);
      setSheetValidation(null);
      if (!file) return;
      await validateSheetFile(file);
    },
    [validateSheetFile]
  );

  const sendDirect = useCallback(async () => {
    if (!resolvedTemplate || !botNumber) {
      showSnackBar(copy.selectTemplateFirst, 'warning');
      return;
    }
    if (!selectedRows.length) {
      showSnackBar(copy.noRecipients, 'warning');
      return;
    }

    if (!areDirectSendOverridesValid(previewParams, paramOverrides)) {
      showSnackBar(copy.direct.fillParamsFirst, 'warning');
      return;
    }

    setIsSubmitting(true);
    setSendSummary(null);
    setSendProgress({ done: 0, total: selectedRows.length });

    try {
      const result = await sendTemplateToLeads({
        selectedRows,
        template: resolvedTemplate,
        botNumber,
        loggedInUser,
        columnsMeta,
        resolveBodyParams: () =>
          applyParamOverridesToBodyParams(previewParams, paramOverrides).map((param) => ({
            type: param.type ?? 'text',
            text: param.text ?? '',
          })),
        onProgress: (done, total) => setSendProgress({ done, total }),
      });

      setSendSummary(result);
      showSnackBar(copy.summary(result.sent, result.failed, result.skipped), result.failed ? 'warning' : 'success');

      if (result.sent > 0) {
        onSuccess?.();
        if (result.failed === 0 && result.skipped === 0) {
          onClose?.();
        }
      }
    } catch {
      showSnackBar(copy.sendFailed, 'error');
    } finally {
      setIsSubmitting(false);
    }
  }, [
    botNumber,
    columnsMeta,
    copy,
    loggedInUser,
    onClose,
    onSuccess,
    paramOverrides,
    previewParams,
    resolvedTemplate,
    selectedRows,
    showSnackBar,
  ]);

  const uploadAndSend = useCallback(async () => {
    if (!resolvedTemplate || !botNumber) {
      showSnackBar(copy.selectTemplateFirst, 'warning');
      return;
    }
    if (!sheetFile) {
      showSnackBar(copy.noSheetFile, 'warning');
      return;
    }

    const validation = sheetValidation ?? (await validateSheetFile(sheetFile));
    if (!validation?.valid) {
      showSnackBar(copy.sheetInvalid, 'error');
      return;
    }

    setIsUploading(true);
    setUploadProgress(0);

    try {
      const formData = new FormData();
      formData.append('file', sheetFile);

      const uploadRes = await templateService.uploadRecipients(
        formData,
        {
          bot_number: botNumber,
          wa_Id: resolvedTemplate.wa_Id,
        },
        (event) => {
          const { loaded, total } = event;
          if (total) {
            setUploadProgress(Math.floor((loaded * 100) / total));
          }
        }
      );

      if (uploadRes?.status !== 200) {
        showSnackBar(parseBulkUploadError(uploadRes) || copy.uploadFailed, 'error');
        return;
      }

      const cronRes = await templateService.sendTemplateCron(resolvedTemplate.wa_Id);
      if (cronRes?.status === 200) {
        showSnackBar(copy.uploadSuccess, 'success');
        onSuccess?.();
        onClose?.();
        return;
      }

      showSnackBar(parseBulkUploadError(cronRes) || copy.uploadFailed, 'error');
    } catch (error) {
      showSnackBar(parseBulkUploadError(error?.response ?? error) || copy.uploadFailed, 'error');
    } finally {
      setIsUploading(false);
    }
  }, [
    botNumber,
    copy,
    onClose,
    onSuccess,
    resolvedTemplate,
    sheetFile,
    sheetValidation,
    showSnackBar,
    validateSheetFile,
  ]);

  return {
    copy,
    subtitle,
    selectedCount: selectedRows.length,
    botNumber,
    organisation,
    quickTemplates,
    selectedTemplateMeta,
    resolvedTemplate,
    isLoadingTemplate,
    isSubmitting,
    isUploading,
    sendProgress,
    sendSummary,
    sheetFile,
    sheetValidation,
    uploadProgress,
    coverage,
    previewParams,
    liveBodyParams,
    isSingleRecipient,
    bulkMappingFields,
    gapLines,
    editableFields,
    columnOptions,
    canSendDirect,
    canUploadSend,
    handleParamChange,
    handleParamColumnSelect,
    selectQuickTemplate,
    handleTemplateDropdownChange,
    handleBotChange,
    downloadPrefilledSample,
    downloadBlankSample,
    downloadErrorSheet,
    handleSheetFileSelect,
    sendDirect,
    uploadAndSend,
  };
}
