import React from 'react';
import {
  Box,
  Drawer,
  Popover,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import FiltersContent from './FiltersContent';

export default function FiltersPanel({
  open,
  anchorEl,
  onClose,
  appliedFilters,
  onApply,
  onClear,
  formItems,
  tableId,
  workspaceId,
  isCampaignOwner = true,
  styles,
}) {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const content = open ? (
    <FiltersContent
      open={open}
      formItems={formItems}
      tableId={tableId}
      workspaceId={workspaceId}
      appliedFilters={appliedFilters}
      onApply={(nextFilters) => {
        onApply(nextFilters);
        onClose();
      }}
      onClear={(emptyFilters) => {
        onClear(emptyFilters);
        onClose();
      }}
      isCampaignOwner={isCampaignOwner}
      styles={styles}
    />
  ) : null;

  if (isMobile) {
    return (
      <Drawer
        anchor="bottom"
        open={open}
        onClose={onClose}
        PaperProps={{
          sx: styles?.recordsFiltersDrawerMobile,
        }}
      >
        <Box sx={styles?.recordsFiltersPanel}>{content}</Box>
      </Drawer>
    );
  }

  return (
    <Popover
      open={open && Boolean(anchorEl)}
      anchorEl={anchorEl}
      onClose={onClose}
      anchorOrigin={{
        vertical: 'bottom',
        horizontal: 'right',
      }}
      transformOrigin={{
        vertical: 'top',
        horizontal: 'right',
      }}
      slotProps={{
        paper: {
          sx: styles?.recordsFiltersPopoverPaper,
        },
      }}
    >
      {content}
    </Popover>
  );
}
