import { templateService } from '../../../whatsapp-templates/services/templateService';
import {
  buildSendTemplatePayload,
  parseTemplateSendError,
} from '../../../whatsapp-templates/utils/templateSendUtils';
import { mapRowToBodyParams } from './leadTemplateParamMapper';
import { resolveLeadPhoneFromRow } from './leadTemplateSendUtils';

const DEFAULT_CONCURRENCY = 3;

async function sendOneLead({
  row,
  template,
  botNumber,
  loggedInUser,
  columnsMeta,
  resolveBodyParams,
}) {
  const phoneResult = resolveLeadPhoneFromRow(row);
  if (!phoneResult.valid) {
    return {
      success: false,
      skipped: true,
      leadId: row?.lead_id ?? row?.id,
      reason: phoneResult.error,
    };
  }

  const mappedParams =
    typeof resolveBodyParams === 'function'
      ? resolveBodyParams(row)
      : mapRowToBodyParams(template, row, loggedInUser, columnsMeta);

  const bodyParams = mappedParams.map(({ type, text }) => ({
    type: type ?? 'text',
    text: text ?? '',
  }));

  const payload = buildSendTemplatePayload({
    formDataToSend: { phone_number: phoneResult.normalized },
    template,
    bodyParams,
    headerComponent: null,
    headerFileUrl: '',
    headerFileName: '',
    useCreateImage: false,
    buttonUrlParams: [],
  });

  if (row?._mongoId || row?._rawLead?.id) {
    payload.lead_id = row._mongoId ?? row._rawLead?.id;
  }

  try {
    const res = await templateService.sendTemplate(payload, botNumber);
    if (res?.status === 200) {
      return {
        success: true,
        skipped: false,
        leadId: row?.lead_id ?? row?.id,
        phone: phoneResult.normalized,
      };
    }
    return {
      success: false,
      skipped: false,
      leadId: row?.lead_id ?? row?.id,
      phone: phoneResult.normalized,
      reason: parseTemplateSendError(res),
    };
  } catch (error) {
    return {
      success: false,
      skipped: false,
      leadId: row?.lead_id ?? row?.id,
      phone: phoneResult.normalized,
      reason: parseTemplateSendError(error?.response ?? error),
    };
  }
}

async function runPool(items, worker, concurrency, onProgress) {
  const results = [];
  let index = 0;
  let completed = 0;

  async function workerLoop() {
    while (index < items.length) {
      const currentIndex = index;
      index += 1;
      const result = await worker(items[currentIndex], currentIndex);
      results[currentIndex] = result;
      completed += 1;
      onProgress?.(completed, items.length);
    }
  }

  const workers = Array.from({ length: Math.min(concurrency, items.length) }, () => workerLoop());
  await Promise.all(workers);
  return results;
}

export async function sendTemplateToLeads({
  selectedRows = [],
  template,
  botNumber,
  loggedInUser,
  columnsMeta = [],
  concurrency = DEFAULT_CONCURRENCY,
  onProgress,
  resolveBodyParams,
}) {
  if (!template || !botNumber) {
    return {
      sent: 0,
      failed: 0,
      skipped: selectedRows.length,
      details: [],
    };
  }

  const details = await runPool(
    selectedRows,
    (row) =>
      sendOneLead({
        row,
        template,
        botNumber,
        loggedInUser,
        columnsMeta,
        resolveBodyParams,
      }),
    concurrency,
    onProgress
  );

  const sent = details.filter((item) => item?.success).length;
  const skipped = details.filter((item) => item?.skipped).length;
  const failed = details.filter((item) => item && !item.success && !item.skipped).length;

  return { sent, failed, skipped, details };
}
