import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSnackBar } from '../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { RECORD_COPY } from '../constants/recordCopy';
import { recordTemplateSummaryService } from '../services/recordTemplateSummaryService';
import {
  getSummaryDate,
  getTemplateDetailPayloadKeys,
  resolveBotNumber,
} from '../utils/statusLogUtils';

const EMPTY_TEMPLATE = {
  name: '',
  id: '',
  data: null,
  sentDate: '',
  sourceStatus: null,
};

export default function useStatusLogTemplate({ botNumber: explicitBotNumber } = {}) {
  const { showSnackBar } = useSnackBar();
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [templateTab, setTemplateTab] = useState('details');
  const [templateDateSummary, setTemplateDateSummary] = useState([]);
  const [templateUsers, setTemplateUsers] = useState([]);
  const [templateUsersTotal, setTemplateUsersTotal] = useState(0);
  const [selectedTemplateDate, setSelectedTemplateDate] = useState('');
  const [templateStartDate, setTemplateStartDate] = useState('');
  const [templateEndDate, setTemplateEndDate] = useState('');
  const [isTemplateLoading, setIsTemplateLoading] = useState(false);
  const [isUsersLoading, setIsUsersLoading] = useState(false);

  const resetTemplateState = useCallback(() => {
    setSelectedTemplate(null);
    setTemplateTab('details');
    setTemplateDateSummary([]);
    setTemplateUsers([]);
    setTemplateUsersTotal(0);
    setSelectedTemplateDate('');
    setTemplateStartDate('');
    setTemplateEndDate('');
    setIsTemplateLoading(false);
    setIsUsersLoading(false);
  }, []);

  const fetchDateSummary = useCallback(async (templateId, startDate = '', endDate = '') => {
    if (!templateId) {
      setTemplateDateSummary([]);
      return [];
    }

    setIsTemplateLoading(true);
    try {
      const data = await recordTemplateSummaryService.getDateWiseSummary(templateId, {
        startDate,
        endDate,
      });
      setTemplateDateSummary(data);
      return data;
    } catch {
      setTemplateDateSummary([]);
      showSnackBar(RECORD_COPY.statusLogs.template.loadDatesError, 'error');
      return [];
    } finally {
      setIsTemplateLoading(false);
    }
  }, [showSnackBar]);

  const fetchUsers = useCallback(async (templateId, date) => {
    if (!templateId || !date) {
      setTemplateUsers([]);
      setTemplateUsersTotal(0);
      return;
    }

    setIsUsersLoading(true);
    try {
      const { users, total } = await recordTemplateSummaryService.getUserSummary(templateId, date);
      setTemplateUsers(users);
      setTemplateUsersTotal(total);
    } catch {
      setTemplateUsers([]);
      setTemplateUsersTotal(0);
      showSnackBar(RECORD_COPY.statusLogs.template.loadUsersError, 'error');
    } finally {
      setIsUsersLoading(false);
    }
  }, [showSnackBar]);

  const openTemplate = useCallback(async ({ row, templateName, sentDate, botNumber }) => {
    if (!templateName) return null;

    const nextTemplate = {
      name: templateName,
      id: '',
      data: row?.template || row,
      sentDate: sentDate || row?.updated_at || row?.created_at || '',
      sourceStatus: row,
    };

    setSelectedTemplate(nextTemplate);
    setTemplateTab('dates');
    setTemplateDateSummary([]);
    setTemplateUsers([]);
    setTemplateUsersTotal(0);
    setSelectedTemplateDate('');
    setTemplateStartDate('');
    setTemplateEndDate('');

    const resolvedBotNumber = botNumber || explicitBotNumber || resolveBotNumber(row);
    const templateId = await recordTemplateSummaryService.resolveTemplateId({
      row,
      templateName,
      botNumber: resolvedBotNumber,
    });

    if (!templateId) {
      showSnackBar(RECORD_COPY.statusLogs.templateIdMissing(templateName), 'warning');
      setSelectedTemplate((prev) => (prev ? { ...prev, id: '' } : prev));
      setTemplateTab('details');
      return null;
    }

    setSelectedTemplate((prev) => (prev ? { ...prev, id: templateId } : prev));
    await fetchDateSummary(templateId);
    return templateId;
  }, [explicitBotNumber, fetchDateSummary, showSnackBar]);

  const handleDateClick = useCallback(async (summaryRow) => {
    const templateId = selectedTemplate?.id;
    const date = getSummaryDate(summaryRow);

    if (!templateId) {
      showSnackBar(RECORD_COPY.statusLogs.template.idMissing, 'warning');
      return;
    }

    if (!date) {
      showSnackBar(RECORD_COPY.statusLogs.template.dateMissing, 'warning');
      return;
    }

    setSelectedTemplateDate(date);
    setTemplateTab('users');
    await fetchUsers(templateId, date);
  }, [fetchUsers, selectedTemplate?.id, showSnackBar]);

  const handleTabChange = useCallback((nextTab) => {
    if (nextTab === 'users' && !selectedTemplateDate) {
      showSnackBar(RECORD_COPY.statusLogs.selectDateFirst, 'warning');
      setTemplateTab('dates');
      return;
    }
    setTemplateTab(nextTab);
  }, [selectedTemplateDate, showSnackBar]);

  const handleDateRangeChange = useCallback(async ({ startDate, endDate }) => {
    setTemplateStartDate(startDate);
    setTemplateEndDate(endDate);

    if (!selectedTemplate?.id) return;
    await fetchDateSummary(selectedTemplate.id, startDate, endDate);
  }, [fetchDateSummary, selectedTemplate?.id]);

  const clearDateRange = useCallback(async () => {
    setTemplateStartDate('');
    setTemplateEndDate('');
    if (!selectedTemplate?.id) return;
    await fetchDateSummary(selectedTemplate.id, '', '');
  }, [fetchDateSummary, selectedTemplate?.id]);

  const templateDetailKeys = useMemo(
    () => getTemplateDetailPayloadKeys(selectedTemplate?.data || {}),
    [selectedTemplate?.data]
  );

  return {
    selectedTemplate,
    templateTab,
    templateDateSummary,
    templateUsers,
    templateUsersTotal,
    selectedTemplateDate,
    templateStartDate,
    templateEndDate,
    isTemplateLoading,
    isUsersLoading,
    templateDetailKeys,
    openTemplate,
    resetTemplateState,
    handleDateClick,
    handleTabChange,
    setTemplateTab,
    handleDateRangeChange,
    clearDateRange,
    fetchDateSummary,
  };
}

export { EMPTY_TEMPLATE };
