/**
 * Pure helpers for single-lead manual template parameter overrides.
 */

export function buildInitialParamOverrides(mappedParams = []) {
  const overrides = {};
  mappedParams.forEach((param) => {
    if (!param?.paramName) return;
    overrides[param.paramName] = String(param.text ?? '');
  });
  return overrides;
}

export function applyParamOverridesToBodyParams(mappedParams = [], overrides = null) {
  if (!overrides || typeof overrides !== 'object') {
    return mappedParams.map(({ type, text }) => ({ type, text: text ?? '' }));
  }

  return mappedParams.map((param) => ({
    type: param.type ?? 'text',
    text: overrides[param.paramName] ?? param.text ?? '',
  }));
}

export function areDirectSendOverridesValid(mappedParams = [], overrides = {}) {
  if (!mappedParams.length) return true;
  return mappedParams.every((param) => {
    const value = overrides[param.paramName] ?? param.text ?? '';
    return String(value).trim().length > 0;
  });
}

export function hasParamOverrideChanges(mappedParams = [], overrides = {}) {
  const baseline = buildInitialParamOverrides(mappedParams);
  const keys = new Set([...Object.keys(baseline), ...Object.keys(overrides)]);
  return Array.from(keys).some(
    (key) => String(overrides[key] ?? '') !== String(baseline[key] ?? '')
  );
}

export function buildEditableParamFields(mappedParams = [], overrides = {}) {
  return mappedParams.map((param, index) => {
    const mappedValue = String(param.text ?? '');
    const currentValue = overrides[param.paramName] ?? mappedValue;
    return {
      ...param,
      variableIndex: index + 1,
      mappedValue,
      value: currentValue,
      isMissingFromRecord: !mappedValue.trim(),
      isValid: Boolean(String(currentValue).trim()),
    };
  });
}
