import APIService from '../../../../../Services/APIService';
import { Apis } from '../../../../../Services/app.constants';
import { LEAD_CHAT_MESSAGE_PAGE_SIZE } from '../constants/leadChatApi';

export const leadChatService = {
  async getMessages(filters = {}) {
    if (!filters?.botNumber || !filters?.phone_number) {
      throw new Error('Bot number and phone number are required');
    }

    const params = new URLSearchParams({
      phone_number: filters.phone_number,
      bot_number: filters.botNumber,
      next_page: String(filters.page || 1),
      page_limit: String(filters.pageLimit || LEAD_CHAT_MESSAGE_PAGE_SIZE),
    });

    const organisationId =
      filters.organisationId || filters.organisation_id || filters.company_id || '';
    if (organisationId) params.set('company_id', String(organisationId));

    return APIService.get(`${Apis.getMasterConversion}?${params.toString()}`);
  },

  async sendMessage(formData, botNumber) {
    if (!botNumber) throw new Error('Bot number is required');
    formData.append('bot_number', botNumber);
    return APIService.post('v0/ui/intervene/send-message/', formData, {
      'Content-Type': 'multipart/form-data',
    });
  },

  async toggleSession(payload) {
    return APIService.post(`${Apis.startEndSession}`, payload);
  },

  async getChatSessionState({ phoneNumber, botNumber, organisationId }) {
    if (!phoneNumber) throw new Error('Phone number is required');
    if (!botNumber) throw new Error('Bot number is required');

    const params = new URLSearchParams({
      phone_number: phoneNumber,
      bot_number: botNumber,
    });

    if (organisationId) {
      params.set('company_id', String(organisationId));
    }

    return APIService.get(`${Apis.getChatSessionState}?${params.toString()}`);
  },
};
