import { normalizeLeadPhone, resolveLeadPhoneFromRow } from '../../utils/leadTemplateSendUtils';

export const CONVERSATION_UNREAD_SOUND_DEBOUNCE_MS = 1000;

export function normalizeUnreadPhone(value) {
  const result = normalizeLeadPhone(value);
  if (result.valid) return result.normalized;

  const digits = `${value ?? ''}`.replace(/\D/g, '');
  if (digits.length === 10) return `91${digits}`;
  return digits || '';
}

export function getRowUnreadPhone(row) {
  const resolved = resolveLeadPhoneFromRow(row);
  if (resolved.valid) return resolved.normalized;
  return normalizeUnreadPhone(row?._rawLead?.phone_number ?? row?.phone_number);
}

export function getRowLeadId(row) {
  const leadId = row?.lead_id ?? row?._rawLead?.lead_id ?? row?.id;
  return leadId == null ? '' : String(leadId);
}

function getRowCreatedAtMs(row) {
  const raw = row?._rawLead?.created_at ?? row?.created_at;
  const time = raw ? Date.parse(raw) : NaN;
  return Number.isNaN(time) ? 0 : time;
}

export function pickCanonicalLeadId(rows, phone) {
  const target = normalizeUnreadPhone(phone);
  if (!target) return '';

  let bestId = '';
  let bestTime = -1;
  let bestLeadId = '';

  (Array.isArray(rows) ? rows : []).forEach((row) => {
    if (getRowUnreadPhone(row) !== target) return;
    const leadId = getRowLeadId(row);
    if (!leadId) return;
    const created = getRowCreatedAtMs(row);
    if (created > bestTime || (created === bestTime && leadId > bestLeadId)) {
      bestTime = created;
      bestLeadId = leadId;
      bestId = leadId;
    }
  });

  return bestId;
}

export function applyConversationUnread(unreadByPhone, payload, { skip = false } = {}) {
  const next = new Map(unreadByPhone instanceof Map ? unreadByPhone : []);
  const phone = normalizeUnreadPhone(payload?.phone_number);
  if (!phone || skip) return next;

  const reported = Number(payload?.not_read_count);
  if (Number.isFinite(reported) && reported >= 0) {
    if (reported === 0) next.delete(phone);
    else next.set(phone, reported);
    return next;
  }

  next.set(phone, (next.get(phone) || 0) + 1);
  return next;
}

export function clearPhoneUnread(unreadByPhone, phone) {
  const next = new Map(unreadByPhone instanceof Map ? unreadByPhone : []);
  const key = normalizeUnreadPhone(phone);
  if (key) next.delete(key);
  return next;
}

export function phoneExistsInRows(rows, phone) {
  const target = normalizeUnreadPhone(phone);
  if (!target) return false;
  return (Array.isArray(rows) ? rows : []).some((row) => getRowUnreadPhone(row) === target);
}

export function buildUnreadCountByLeadId(rows, unreadByPhone) {
  const counts = new Map();
  const source = unreadByPhone instanceof Map ? unreadByPhone : new Map();

  source.forEach((count, phone) => {
    if (!count) return;
    const leadId = pickCanonicalLeadId(rows, phone);
    if (leadId) counts.set(leadId, count);
  });

  return counts;
}

export function getUnreadCountForRow(row, unreadCountByLeadId) {
  if (!unreadCountByLeadId) return 0;
  return unreadCountByLeadId.get(getRowLeadId(row)) || 0;
}

export function shouldPlayConversationUnreadSound({
  phone,
  lastPlayedAt = 0,
  now = Date.now(),
  debounceMs = CONVERSATION_UNREAD_SOUND_DEBOUNCE_MS,
} = {}) {
  if (!normalizeUnreadPhone(phone)) return false;
  return now - lastPlayedAt >= debounceMs;
}
