import React, { useMemo } from 'react';
import {
  Box,
  Checkbox,
  Chip,
  Divider,
  Drawer,
  Typography,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import { Button } from '../../../../components/ui';
import { RECORD_COPY } from '../constants/recordCopy';

function isColumnVisible(columnVisibility, key) {
  return columnVisibility[key] !== false;
}

function ColumnToggleRow({
  checked,
  label,
  onChange,
  indeterminate = false,
  bold = false,
  styles,
}) {
  return (
    <Box
      component="label"
      sx={[
        styles?.recordsColumnsItem,
        bold ? styles?.recordsColumnsItemBold : null,
      ]}
    >
      <Checkbox
        size="small"
        checked={checked}
        indeterminate={indeterminate}
        onChange={onChange}
        sx={styles?.recordsColumnsCheckbox}
        tabIndex={-1}
      />
      <Typography
        component="span"
        sx={[
          styles?.recordsColumnsItemLabel,
          bold ? styles?.recordsColumnsItemLabelBold : null,
        ]}
      >
        {label}
      </Typography>
    </Box>
  );
}

export default function ColumnsMenu({
  open,
  onClose,
  columns = [],
  columnVisibility = {},
  onToggleColumn,
  onSetAllColumnsVisible,
  onResetColumns,
  onSaveView,
  isSaving = false,
  styles,
}) {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const columnKeys = useMemo(
    () => columns.map((column) => column.key).filter(Boolean),
    [columns]
  );

  const visibleCount = useMemo(
    () => columnKeys.filter((key) => isColumnVisible(columnVisibility, key)).length,
    [columnKeys, columnVisibility]
  );

  const allVisible = columnKeys.length > 0 && visibleCount === columnKeys.length;
  const isIndeterminate = visibleCount > 0 && visibleCount < columnKeys.length;

  return (
    <Drawer
      anchor={isMobile ? 'bottom' : 'right'}
      open={open}
      onClose={onClose}
      PaperProps={{
        sx: isMobile
          ? styles?.recordsColumnsDrawerMobile
          : styles?.recordsColumnsDrawerDesktop,
      }}
    >
      <Box sx={styles?.recordsColumnsPanel}>
        <Box sx={styles?.recordsColumnsHeader}>
          <Box sx={styles?.recordsColumnsHeaderText}>
            <Typography sx={styles?.recordsFiltersTitle}>{RECORD_COPY.columns}</Typography>
            <Typography sx={styles?.recordsColumnsHelper}>
              {RECORD_COPY.columnsMenu.helper}
            </Typography>
          </Box>
          {columnKeys.length > 0 ? (
            <Chip
              label={RECORD_COPY.columnsMenu.visibleCount(visibleCount, columnKeys.length)}
              size="small"
              sx={styles?.recordsColumnsCountChip}
            />
          ) : null}
        </Box>

        <Divider sx={styles?.recordsColumnsDivider} />

        <Box sx={styles?.recordsColumnsMasterRow}>
          <ColumnToggleRow
            checked={allVisible}
            indeterminate={isIndeterminate}
            label={RECORD_COPY.columnsMenu.selectAll}
            bold
            styles={styles}
            onChange={(event) => onSetAllColumnsVisible?.(event.target.checked)}
          />
          <Button
            variant="ghost"
            size="sm"
            onClick={onResetColumns}
            disabled={!columnKeys.length}
            sx={styles?.recordsColumnsResetButton}
          >
            {RECORD_COPY.columnsMenu.reset}
          </Button>
        </Box>

        <Box sx={styles?.recordsColumnsList}>
          {columns.length === 0 ? (
            <Typography sx={styles?.recordsColumnsEmpty}>
              No columns available
            </Typography>
          ) : (
            columns.map((column) => (
              <ColumnToggleRow
                key={column.key}
                checked={isColumnVisible(columnVisibility, column.key)}
                label={column.header}
                styles={styles}
                onChange={() => onToggleColumn(column.key)}
              />
            ))
          )}
        </Box>

        <Box sx={styles?.recordsColumnsFooter}>
          <Box
            sx={{
              display: 'flex',
              gap: 1,
              width: isMobile ? '100%' : 'auto',
              justifyContent: 'flex-end',
            }}
          >
            <Button
              variant="outline"
              fullWidth={isMobile}
              onClick={onClose}
            >
              {RECORD_COPY.columnsMenu.close}
            </Button>
            {onSaveView ? (
              <Button
                variant="primary"
                fullWidth={isMobile}
                loading={isSaving}
                onClick={() => onSaveView(columnVisibility)}
              >
                {RECORD_COPY.saveView}
              </Button>
            ) : null}
          </Box>
        </Box>
      </Box>
    </Drawer>
  );
}
