import * as XLSX from 'xlsx';
import { getBulkSheetParamColumns } from '../../../whatsapp-templates/utils/bulkSheetValidation';
import { mapRowToSheetRowWithColumnMap } from './leadTemplateBulkColumnMap';
import { resolveLeadPhoneFromRow } from './leadTemplateSendUtils';

export function buildSampleSheetRows(
  template,
  selectedRows = [],
  loggedInUser = null,
  columnsMeta = [],
  paramColumnMap = null
) {
  const paramColumns = getBulkSheetParamColumns(template);

  return selectedRows.map((row, index) => {
    const phoneResult = resolveLeadPhoneFromRow(row);
    const mapped = mapRowToSheetRowWithColumnMap(
      template,
      row,
      loggedInUser,
      columnsMeta,
      paramColumnMap ?? {}
    );
    const sheetRow = {
      phone_number: phoneResult.valid ? phoneResult.normalized : '',
      ...mapped,
    };

    paramColumns.forEach((col) => {
      if (sheetRow[col] == null) {
        sheetRow[col] = mapped[col] ?? '';
      }
    });

    return {
      rowIndex: index,
      rowNumber: index + 2,
      row: sheetRow,
    };
  });
}

export function buildLeadTemplateSampleSheetWorkbook(
  template,
  selectedRows = [],
  loggedInUser = null,
  columnsMeta = [],
  paramColumnMap = null
) {
  const paramColumns = getBulkSheetParamColumns(template);
  const rows = buildSampleSheetRows(
    template,
    selectedRows,
    loggedInUser,
    columnsMeta,
    paramColumnMap
  ).map((entry) => entry.row);

  const orderedColumns = ['phone_number', ...paramColumns.filter((col) => col !== 'phone_number')];
  const normalizedRows = rows.map((row) => {
    const ordered = {};
    orderedColumns.forEach((key) => {
      ordered[key] = row[key] ?? '';
    });
    return ordered;
  });

  const worksheet = XLSX.utils.json_to_sheet(normalizedRows, { header: orderedColumns });
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, 'data');
  return workbook;
}

export function downloadLeadTemplateSampleSheet(
  template,
  selectedRows = [],
  loggedInUser = null,
  columnsMeta = [],
  paramColumnMap = null
) {
  const workbook = buildLeadTemplateSampleSheetWorkbook(
    template,
    selectedRows,
    loggedInUser,
    columnsMeta,
    paramColumnMap
  );
  const safeName = String(template?.name ?? 'template').replace(/[^\w.-]+/g, '_');
  const stamp = new Date().toISOString().slice(0, 10);
  XLSX.writeFile(workbook, `template-send-${safeName}-${stamp}.xlsx`);
}
