import React from 'react';
import {
  Box,
  Checkbox,
  FormControlLabel,
  FormGroup,
  Popover,
  Typography,
} from '@mui/material';
import { Button } from '../../../../../components/ui';
import { useFeatureTheme } from '../../../../../theme/hooks/useFeatureTheme';
import { RECORD_COPY } from '../../constants/recordCopy';

export default function StatusLogPayloadColumnsMenu({
  anchorEl,
  onClose,
  payloadKeys = [],
  selectedPayloadFields = [],
  onToggleField,
  onToggleAll,
}) {
  const { semantic, typography } = useFeatureTheme();
  const copy = RECORD_COPY.statusLogs;
  const allSelected = payloadKeys.length > 0
    && payloadKeys.every((key) => selectedPayloadFields.includes(key));
  const someSelected = payloadKeys.some((key) => selectedPayloadFields.includes(key));

  return (
    <Popover
      open={Boolean(anchorEl)}
      anchorEl={anchorEl}
      onClose={onClose}
      anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      transformOrigin={{ vertical: 'top', horizontal: 'right' }}
      slotProps={{
        paper: {
          sx: {
            mt: 0.5,
            width: { xs: 'min(360px, calc(100vw - 32px))', sm: 360 },
            maxHeight: { xs: 'min(420px, calc(100dvh - 120px))', sm: 420 },
            border: `1px solid ${semantic.borders.border}`,
            borderRadius: 2,
            boxShadow: '0 8px 24px rgba(15, 23, 42, 0.12)',
          },
        },
      }}
    >
      <Box sx={{ p: 2, overflow: 'auto', maxHeight: 'inherit' }}>
        <Typography
          sx={{
            fontSize: typography.fontSizeSm,
            fontWeight: typography.fontWeightSemibold,
            color: semantic.text.primary,
            mb: 1,
          }}
        >
          {copy.payloadColumns}
        </Typography>

        {payloadKeys.length === 0 ? (
          <Typography
            sx={{
              fontSize: typography.fontSizeSm,
              color: semantic.text.secondary,
            }}
          >
            {copy.payloadColumnsEmpty}
          </Typography>
        ) : (
          <>
            <FormControlLabel
              control={
                <Checkbox
                  checked={allSelected}
                  indeterminate={!allSelected && someSelected}
                  onChange={(event) => onToggleAll?.(event.target.checked)}
                />
              }
              label={RECORD_COPY.columnsMenu.selectAll}
              sx={{ ml: 0 }}
            />
            <FormGroup sx={{ mt: 0.5 }}>
              {payloadKeys.map((key) => (
                <FormControlLabel
                  key={key}
                  control={
                    <Checkbox
                      checked={selectedPayloadFields.includes(key)}
                      onChange={() => onToggleField?.(key)}
                    />
                  }
                  label={
                    <Typography
                      sx={{
                        fontSize: typography.fontSizeSm,
                        wordBreak: 'break-word',
                      }}
                    >
                      {key}
                    </Typography>
                  }
                  sx={{ alignItems: 'flex-start', ml: 0 }}
                />
              ))}
            </FormGroup>
          </>
        )}

        <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 1.5 }}>
          <Button variant="secondary" size="sm" onClick={onClose}>
            {RECORD_COPY.columnsMenu.close}
          </Button>
        </Box>
      </Box>
    </Popover>
  );
}
