import React from 'react';
import {
  Alert,
  Box,
  Chip,
  IconButton,
  InputBase,
  Tooltip,
} from '@mui/material';
import AddRoundedIcon from '@mui/icons-material/AddRounded';
import SendRoundedIcon from '@mui/icons-material/SendRounded';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';
import {
  canComposeFreeForm,
  canOpenComposerAttachMenu,
} from '../utils/leadChatComposerMode';
import useLeadChatComposer from '../hooks/useLeadChatComposer';
import useLeadChatSx from '../hooks/useLeadChatSx';
import { formatAttachmentFileSize } from '../utils/leadChatAttachmentUtils';
import LeadChatComposerAttachMenu from './LeadChatComposerAttachMenu';

export default function LeadChatComposer({
  draft,
  onDraftChange,
  isSending,
  composerMode,
  canUseChat = true,
  canSendTemplate = false,
  onSendMessage,
  onOpenSendTemplate,
  shouldStickToBottomRef,
}) {
  const sx = useLeadChatSx();
  const composer = useLeadChatComposer({ onSendMessage, shouldStickToBottomRef });
  const canCompose = canUseChat && canComposeFreeForm(composerMode);
  const canOpenAttach = canUseChat && canOpenComposerAttachMenu(composerMode, canSendTemplate);

  if (!canUseChat) {
    return (
      <Box sx={sx.composer}>
        <Alert severity="warning" sx={{ borderRadius: '6px' }}>
          {LEAD_CHAT_COPY.composer.noPermission}
        </Alert>
      </Box>
    );
  }

  return (
    <Box sx={sx.composer}>
      <input
        ref={composer.fileInputRef}
        type="file"
        hidden
        onChange={composer.handleFileSelect}
      />

      {composer.selectedFile ? (
        <Chip
          label={LEAD_CHAT_COPY.composer.fileSelected(
            composer.selectedFile.name,
            formatAttachmentFileSize(composer.selectedFile.size)
          )}
          onDelete={composer.clearSelectedFile}
          size="small"
          sx={sx.composerFileChip}
        />
      ) : null}

      {composer.fileError ? (
        <Alert severity="warning" onClose={composer.clearFileError} sx={{ borderRadius: '6px' }}>
          {composer.fileError}
        </Alert>
      ) : null}

      <Box sx={sx.composerInputWrap}>
        <Tooltip
          title={
            canOpenAttach && !canCompose
              ? LEAD_CHAT_COPY.composer.attachIdle
              : LEAD_CHAT_COPY.composer.attach
          }
        >
          <IconButton
            ref={composer.attachButtonRef}
            size="small"
            sx={sx.composerAttachButton}
            onClick={composer.openAttachMenu}
            disabled={!canOpenAttach}
          >
            <AddRoundedIcon sx={{ fontSize: 20 }} />
          </IconButton>
        </Tooltip>

        <InputBase
          multiline
          maxRows={4}
          placeholder={LEAD_CHAT_COPY.composer.placeholder}
          value={draft}
          onChange={(e) => onDraftChange?.(e.target.value)}
          onKeyDown={canCompose ? composer.handleKeyDown : undefined}
          disabled={!canCompose}
          sx={sx.composerInput}
        />

        <Tooltip title={LEAD_CHAT_COPY.composer.send}>
          <span>
            <IconButton
              sx={sx.composerSendButton}
              onClick={composer.handleSend}
              disabled={!canCompose || isSending || (!draft.trim() && !composer.selectedFile)}
            >
              <SendRoundedIcon sx={{ fontSize: 18 }} />
            </IconButton>
          </span>
        </Tooltip>
      </Box>

      <LeadChatComposerAttachMenu
        anchorEl={composer.attachButtonRef.current}
        open={composer.attachMenuOpen}
        onClose={composer.closeAttachMenu}
        canSendTemplate={canSendTemplate}
        canAttachMedia={canCompose}
        onPickTemplate={() => onOpenSendTemplate?.()}
        onPickImage={() => {
          if (!canCompose) return;
          composer.openAttachmentPicker('image');
        }}
        onPickVideo={() => {
          if (!canCompose) return;
          composer.openAttachmentPicker('video');
        }}
        onPickDocument={() => {
          if (!canCompose) return;
          composer.openAttachmentPicker('document');
        }}
      />
    </Box>
  );
}
