import { getLeadFieldValue } from '../../adapters/tableRecordsAdapter';
import { getBodyParamLabels } from '../../../whatsapp-templates/utils/templateSendUtils';

export function divideKeyType(paramName) {
  const raw = String(paramName ?? '').trim();
  if (!raw) return { role: '', key: '' };

  const [role, ...rest] = raw.split('_');
  return { role: role ?? '', key: rest.join('_') };
}

function resolveFromLoggedInUser(loggedInUser, key) {
  if (!loggedInUser || !key) return '';

  const profile = loggedInUser.profile ?? {};
  const direct = loggedInUser[key] ?? profile[key];
  if (direct != null && direct !== '') {
    return String(direct);
  }

  if (key === 'username') {
    return String(loggedInUser.username ?? profile.username ?? '');
  }
  if (key === 'mobile' || key === 'phone') {
    return String(loggedInUser.mobile ?? profile.mobile ?? '');
  }

  return '';
}

function resolveFromRow(row, key, columnsMeta = []) {
  if (!row || !key) return '';

  if (row[key] != null && row[key] !== '') {
    return String(row[key]);
  }

  const rawLead = row._rawLead ?? row;
  const fromLead = getLeadFieldValue(rawLead, key);
  if (fromLead != null && fromLead !== '') {
    return String(fromLead);
  }

  const column = (columnsMeta ?? []).find(
    (item) =>
      item?.key === key
      || item?.fieldMeta?.key_name === key
      || item?.header === key
      || item?.fieldMeta?.alias_name === key
  );
  if (column?.key && row[column.key] != null && row[column.key] !== '') {
    return String(row[column.key]);
  }

  return '';
}

export function resolveParamValue(paramName, row, loggedInUser, columnsMeta = []) {
  const { role, key } = divideKeyType(paramName);

  if (role === 'agent') {
    return resolveFromLoggedInUser(loggedInUser, key);
  }
  if (role === 'lead') {
    return resolveFromRow(row, key, columnsMeta);
  }
  if (role === 'user') {
    return '';
  }

  const byKey = resolveFromRow(row, paramName, columnsMeta);
  if (byKey) return byKey;

  const byLabel = resolveFromRow(row, key, columnsMeta);
  return byLabel;
}

export function getTemplateParamNames(template) {
  const labels = getBodyParamLabels(template);
  const paramNames = Array.isArray(template?.param) ? template.param : [];
  if (paramNames.length) {
    return paramNames.map((name, index) => ({
      name: String(name),
      label: labels[index] ?? String(name),
    }));
  }
  return labels.map((label) => ({ name: String(label), label: String(label) }));
}

export function mapRowToBodyParams(template, row, loggedInUser, columnsMeta = []) {
  return getTemplateParamNames(template).map(({ name, label }) => ({
    type: 'text',
    text: resolveParamValue(name, row, loggedInUser, columnsMeta),
    label,
    paramName: name,
  }));
}

export function mapRowToSheetRow(template, row, loggedInUser, columnsMeta = []) {
  const sheetRow = {};
  getTemplateParamNames(template).forEach(({ name, label }) => {
    sheetRow[label] = resolveParamValue(name, row, loggedInUser, columnsMeta);
  });
  return sheetRow;
}
