/**
 * Extract a user-facing error message from an Intervene / coreapi response.
 */
export function parseLeadChatApiError(res, fallback = 'Request failed') {
  const payload = res?.data;
  if (payload?.status === true) {
    return '';
  }

  const data = payload?.data ?? payload;
  if (typeof data === 'string' && data.trim()) {
    return data;
  }

  const generalError = data?.general_error;
  if (typeof generalError === 'string' && generalError.trim()) {
    return generalError;
  }
  if (generalError?.error?.message) {
    return generalError.error.message;
  }
  if (generalError?.message) {
    return generalError.message;
  }
  if (typeof payload?.message === 'string' && payload.message.trim()) {
    return payload.message;
  }
  return fallback;
}

export function isLeadChatApiSuccess(res) {
  return res?.status === 200 && payloadIsSuccess(res?.data);
}

function payloadIsSuccess(payload) {
  if (payload == null) return true;
  if (typeof payload?.status === 'boolean') {
    return payload.status;
  }
  return true;
}
