import { useCallback, useEffect, useMemo, useState } from 'react';
import { buildStatusLogRows, collectPayloadKeys, extractStatusLogList } from '../adapters/statusLogAdapter';
import { RECORD_COPY } from '../constants/recordCopy';
import { recordStatusLogService } from '../services/recordStatusLogService';

export default function useStatusLogs({ open, leadId }) {
  const [rows, setRows] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [selectedPayloadFields, setSelectedPayloadFields] = useState([]);

  const fetchLogs = useCallback(async () => {
    if (!leadId) {
      setRows([]);
      return;
    }

    setIsLoading(true);
    setError('');

    try {
      const response = await recordStatusLogService.fetchStatusLogs(leadId);
      if (response?.status === 200 || response?.status === 201) {
        const list = buildStatusLogRows(extractStatusLogList(response));
        setRows(list);
      } else {
        setRows([]);
        setError(RECORD_COPY.statusLogs.loadError);
      }
    } catch {
      setRows([]);
      setError(RECORD_COPY.statusLogs.loadError);
    } finally {
      setIsLoading(false);
    }
  }, [leadId]);

  useEffect(() => {
    if (!open) {
      setSelectedPayloadFields([]);
      setError('');
      return;
    }
    fetchLogs();
  }, [fetchLogs, open]);

  const payloadKeys = useMemo(() => collectPayloadKeys(rows), [rows]);

  const togglePayloadField = useCallback((key) => {
    setSelectedPayloadFields((prev) => (
      prev.includes(key) ? prev.filter((item) => item !== key) : [...prev, key]
    ));
  }, []);

  const setAllPayloadFields = useCallback((checked) => {
    setSelectedPayloadFields(checked ? payloadKeys : []);
  }, [payloadKeys]);

  return {
    rows,
    isLoading,
    error,
    payloadKeys,
    selectedPayloadFields,
    togglePayloadField,
    setAllPayloadFields,
    refetch: fetchLogs,
  };
}
