import { normalizeFormItems } from './dynamicFilterUtils';

export function getStatusFieldDefinitions(formItems) {
  return normalizeFormItems(formItems).filter(
    (field) =>
      field?.access_level !== 'none'
      && field?.key_type === 'DROPDOWN'
      && (field?.statusOption === 'is_status' || field?.statusOption === 'is_sub_status')
  );
}

export function getStatusTypeKeys(dynamicFormFields = []) {
  return dynamicFormFields
    .filter((field) => field?.key_type === 'DROPDOWN' && field?.statusOption === 'is_status')
    .map((field) => field.key_name);
}

export function buildStatusDataFromSelection(selection = {}, dynamicFormFields = []) {
  const data = [];
  const statusTypes = getStatusTypeKeys(dynamicFormFields);

  statusTypes.forEach((typeKey) => {
    const statusObj = selection[typeKey]?.status;
    if (!statusObj) return;

    data.push({
      type_of_status: typeKey,
      status: statusObj.status_name || statusObj.alias_name,
      status_name: statusObj.status_name || statusObj.alias_name,
      status_id: statusObj.status_id,
    });

    const subKey = dynamicFormFields.find(
      (field) => field?.status_parent_key === typeKey
    )?.key_name;

    const subStatusObj = subKey ? selection[subKey]?.subStatus : null;

    if (subStatusObj) {
      data.push({
        type_of_status: subKey,
        status_name: statusObj.status_name || statusObj.alias_name,
        status_id: statusObj.status_id,
        sub_status_id: subStatusObj.sub_status_id,
        sub_status_name: subStatusObj.name,
      });
    }
  });

  return data;
}

export function buildBulkStatusPayload(recordIds = [], selection = {}, dynamicFormFields = []) {
  const payloadData = [];

  recordIds.forEach((recordId) => {
    buildStatusDataFromSelection(selection, dynamicFormFields).forEach((entry) => {
      payloadData.push({
        id: recordId,
        ...entry,
      });
    });
  });

  return {
    lead_ids: recordIds,
    data: payloadData,
  };
}
