import { useEffect, useRef } from 'react';
import { useSetRecoilState } from 'recoil';
import { campaignLeadManagementAtom } from '../../../../Services/_states';
import { recordService } from '../services/recordService';
import { normalizeFormItems } from '../utils/dynamicFilterUtils';

/**
 * Syncs status/form context into campaignLeadManagementAtom so DynamicFormFieldsList
 * can render status/sub-status dropdowns outside the legacy Lead module shell.
 */
export default function useStatusContext({
  open,
  workspaceId,
  table,
  webForm,
  formItems,
}) {
  const setCampaignLeadManagement = useSetRecoilState(campaignLeadManagementAtom);
  const syncedFormIdRef = useRef(null);

  useEffect(() => {
    if (!open || !table?.id) {
      syncedFormIdRef.current = null;
      return undefined;
    }

    let cancelled = false;
    const formId = String(table.id);

    const syncContext = async () => {
      const statusList = await recordService.fetchStatusList(formId);
      if (cancelled) return;

      const resolvedFormItems =
        webForm?.leads_form_items
        ?? formItems
        ?? table?.leadsFormItems
        ?? {};

      setCampaignLeadManagement((prev) => ({
        ...prev,
        selectedCampaign: {
          proposal_id: workspaceId,
          name: table?.campaignName || table?.name || 'Campaign',
        },
        selectedForm: {
          leads_form_id: table.id,
          leads_form_name: table?.name,
          leads_form_items: resolvedFormItems,
        },
        statusData: {
          ...(prev?.statusData ?? {}),
          [formId]: statusList,
        },
      }));

      syncedFormIdRef.current = formId;
    };

    syncContext();

    return () => {
      cancelled = true;
      const syncedFormId = syncedFormIdRef.current;
      if (!syncedFormId) return;

      setCampaignLeadManagement((prev) => {
        const nextStatusData = { ...(prev?.statusData ?? {}) };
        delete nextStatusData[syncedFormId];

        return {
          ...prev,
          selectedCampaign: prev?.selectedForm?.leads_form_id === table?.id
            ? undefined
            : prev?.selectedCampaign,
          selectedForm: prev?.selectedForm?.leads_form_id === table?.id
            ? undefined
            : prev?.selectedForm,
          statusData: nextStatusData,
        };
      });

      syncedFormIdRef.current = null;
    };
  }, [open, workspaceId, table, webForm, formItems, setCampaignLeadManagement]);
}
